// Mock service scheduling (fictional) - stands in for a fleet management API
const a = $('Predictive Maintenance Agent').item.json.output;
const v = $('Split Vehicle Records').item.json;
const d = new Date(); d.setDate(d.getDate() + (a.urgency === 'critical' ? 1 : a.urgency === 'high' ? 3 : 7));
return { json: { vehicle_id: a.vehicle_id, vehicle_type: v.type, urgency: a.urgency, predicted_issue: a.predicted_issue, recommended_action: a.recommended_action, rationale: a.rationale, appointment_id: 'SVC-' + Math.floor(Math.random()*90000+10000), appointment_date: d.toISOString().slice(0,10), shop: 'Demo Fleet Service Center' } };

